  constexpr size_t stride = Typed ? 136 : 136;
  const Seed_fixtures_21<Typed> seed{seeds + r * stride};
  row[layout.auxiliaries] = seed.word(0);
  const uint32_t status = row_fixtures_21(seed, layout, row);
  if (status) atomicCAS(error, 0U, status);
}
cudaError_t launch_fixtures_21(const uint8_t* seeds, uint32_t encoding, size_t real, size_t rows, Layout layout, uint64_t* output, uint32_t* error) {
